style.css:
@-moz-document domain("youtube.com") {
/* Color de fondo principal */
    :root {
        --yt-spec-general-background-a: #1a0808;
        --yt-spec-base-background: #140606;
        --yt-spec-raised-background: #250909;
        --yt-spec-menu-background: #330c0c;
        --yt-spec-brand-background-primary: #a30000;
        --yt-spec-brand-background-secondary: #e60000;
        --yt-spec-text-primary: #ffffff;
        --yt-spec-text-secondary: #ffb3b3;
        --yt-spec-text-disabled: #663333;
        --yt-spec-icon-active-other: #ff0000;
        --yt-spec-icon-inactive-other: #cc0000;
        --yt-spec-filled-icon-active: #ff0000;
        --yt-spec-filled-icon-inactive: #e60000;
        --yt-spec-suggested-action: #ff0000;
        --yt-spec-call-to-action: #ff0000;
    }

    /* Fondo del cuerpo de la página */
    body {
        background-color: var(--yt-spec-base-background) !important;
    }

    /* Fondo de la barra de navegación y el reproductor */
    ytd-app,
    ytd-page-manager {
        background-color: var(--yt-spec-base-background) !important;
    }

    /* Tarjetas de video, miniaturas y secciones */
    .ytd-rich-grid-row,
    ytd-rich-grid-media,
    ytd-compact-video-renderer,
    #info-contents {
        background-color: var(--yt-spec-raised-background) !important;
    }

    /* Botones, controles y elementos interactivos */
    .yt-spec-button-shape-next--filled,
    .yt-spec-button-shape-next--call-to-action {
        background-color: var(--yt-spec-call-to-action) !important;
        color: white !important;
    }

    /* Color de los iconos y enlaces principales */
    ytd-masthead #end #buttons ytd-topbar-menu-button-renderer {
        color: var(--yt-spec-icon-active-other) !important;
    }
    ytd-compact-link-renderer {
        color: var(--yt-spec-suggested-action) !important;
    }

    /* Títulos de videos y texto principal */
    h3,
    yt-formatted-string,
    #video-title {
        color: var(--yt-spec-text-primary) !important;
    }
}
